-- Vector-store tables are deliberately not hand-written here. Configure and
-- migrate the Spring AI-managed vector schema during the application update.
-- END V001__create_furniture_shop.sql

-- BEGIN V002__orders_request_fingerprint.sql
-- Additive migration after V001; select the target database explicitly before execution.
-- Existing historical rows remain NULL; only new checkout orders use replay matching.
ALTER TABLE orders ADD COLUMN IF NOT EXISTS request_fingerprint CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL;
-- END V002__orders_request_fingerprint.sql

-- BEGIN V003__shipments_idempotency.sql
-- Apply after V002 to the selected furniture_shop schema.
ALTER TABLE shipments ADD COLUMN IF NOT EXISTS idempotency_key VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_shipments_idempotency ON shipments(idempotency_key);
-- END V003__shipments_idempotency.sql

-- BEGIN V004__shipment_audit_index.sql
-- Apply after V003 to the selected furniture_shop schema. Keeps the approved 45-table model.
CREATE INDEX IF NOT EXISTS idx_audit_shipment_request
    ON audit_logs(entity_type,action,request_id);
-- END V004__shipment_audit_index.sql

-- BEGIN V005__orders_assembly_requested.sql
-- Additive after V004. Preserve the requested service even when its fee is zero.
ALTER TABLE orders ADD COLUMN IF NOT EXISTS assembly_requested BOOLEAN NOT NULL DEFAULT FALSE CHECK(assembly_requested IN (0,1));
-- Historical checkout only stored the fee; positive fee is unambiguous evidence.
UPDATE orders SET assembly_requested=TRUE WHERE assembly_fee>0 AND assembly_requested=FALSE;
-- END V005__orders_assembly_requested.sql

-- BEGIN V006__payments_confirmation_note.sql
-- Additive after V005. Private verification evidence; customer APIs exclude it.
ALTER TABLE payments ADD COLUMN IF NOT EXISTS confirmation_note VARCHAR(1000) NULL;
-- END V006__payments_confirmation_note.sql

-- BEGIN V007__refunds_verification_notes.sql
-- Private staff evidence; financial history and public refund reason remain unchanged.
ALTER TABLE refunds ADD COLUMN IF NOT EXISTS confirmation_note VARCHAR(1000) NULL;
ALTER TABLE refunds ADD COLUMN IF NOT EXISTS resolution_note VARCHAR(1000) NULL;
-- END V007__refunds_verification_notes.sql

-- BEGIN V008__commerce_operations.sql
-- UTC deadlines only for newly opted-in COD orders. No legacy order backfill.
ALTER TABLE orders ADD COLUMN IF NOT EXISTS confirmation_expires_at DATETIME(6) NULL;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS expiry_attempts INT NOT NULL DEFAULT 0;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS expiry_retry_after DATETIME(6) NULL;
CREATE INDEX IF NOT EXISTS idx_orders_confirmation_expiry ON orders(status,confirmation_expires_at,id);

CREATE TABLE IF NOT EXISTS commerce_notification_outbox (
    id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    event_key VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    order_id BIGINT NOT NULL,
    recipient_user_id BIGINT NOT NULL,
    notification_type VARCHAR(50) NOT NULL,
    title VARCHAR(200) NOT NULL,
    body VARCHAR(1000) NOT NULL,
    state VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    attempts INT NOT NULL DEFAULT 0,
    next_attempt_at DATETIME(6) NOT NULL,
    last_error VARCHAR(100),
    created_at DATETIME(6) NOT NULL,
    updated_at DATETIME(6) NOT NULL,
    sent_at DATETIME(6),
    CONSTRAINT uq_commerce_outbox_event UNIQUE(event_key),
    CONSTRAINT ck_commerce_outbox_state CHECK(state IN ('PENDING','RETRY','SENT','DEAD')),
    CONSTRAINT ck_commerce_outbox_attempts CHECK(attempts>=0),
    CONSTRAINT fk_commerce_outbox_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,
    CONSTRAINT fk_commerce_outbox_recipient FOREIGN KEY(recipient_user_id) REFERENCES users(id) ON DELETE CASCADE,
    KEY idx_commerce_outbox_due(state,next_attempt_at,id)
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS commerce_notifications (
    id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    outbox_id BIGINT NOT NULL,
    recipient_user_id BIGINT NOT NULL,
    order_id BIGINT NOT NULL,
    notification_type VARCHAR(50) NOT NULL,
    title VARCHAR(200) NOT NULL,
    body VARCHAR(1000) NOT NULL,
    created_at DATETIME(6) NOT NULL,
    read_at DATETIME(6),
    CONSTRAINT uq_commerce_notification_event UNIQUE(outbox_id),
    CONSTRAINT fk_commerce_notification_event FOREIGN KEY(outbox_id) REFERENCES commerce_notification_outbox(id) ON DELETE CASCADE,
    CONSTRAINT fk_commerce_notification_order FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,
    CONSTRAINT fk_commerce_notification_recipient FOREIGN KEY(recipient_user_id) REFERENCES users(id) ON DELETE CASCADE,
    KEY idx_commerce_notifications_page(recipient_user_id,created_at,id),
    KEY idx_commerce_notifications_unread(recipient_user_id,read_at,created_at,id)
) ENGINE=InnoDB;
-- END V008__commerce_operations.sql

-- BEGIN V009__commerce_read_indexes.sql
-- Measured EXPLAIN: global first-page order/payment lists avoid filesort.
-- Deep offsets may still choose full scan; no forced plan or HTTP latency guarantee.
CREATE INDEX IF NOT EXISTS idx_orders_time ON orders(placed_at,id);
CREATE INDEX IF NOT EXISTS idx_payments_time ON payments(created_at,id);
CREATE INDEX IF NOT EXISTS idx_payments_status_time ON payments(status,created_at,id);
-- END V009__commerce_read_indexes.sql

-- BEGIN V010__sepay_payment_snapshots.sql
-- Nullable snapshots preserve all existing COD/manual payments. No secrets stored.
ALTER TABLE payments
    ADD COLUMN IF NOT EXISTS sepay_code VARCHAR(10) CHARACTER SET ascii COLLATE ascii_bin,
    ADD COLUMN IF NOT EXISTS sepay_bank VARCHAR(50),
    ADD COLUMN IF NOT EXISTS sepay_account_number VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
    ADD COLUMN IF NOT EXISTS sepay_account_holder VARCHAR(150),
    ADD COLUMN IF NOT EXISTS sepay_content VARCHAR(200);
CREATE UNIQUE INDEX IF NOT EXISTS uq_payments_sepay_code ON payments(sepay_code);
-- END V010__sepay_payment_snapshots.sql

-- BEGIN V011__sepay_automation_review.sql
-- Additive only. Existing attempts retain NULL expiry and are never backfilled.
ALTER TABLE payments
 ADD COLUMN IF NOT EXISTS sepay_transaction_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
 ADD COLUMN IF NOT EXISTS sepay_bank_account_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
 ADD COLUMN IF NOT EXISTS sepay_next_check_at DATETIME(6),
 ADD COLUMN IF NOT EXISTS sepay_lease_token CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
 ADD COLUMN IF NOT EXISTS sepay_lease_until DATETIME(6),
 ADD COLUMN IF NOT EXISTS sepay_check_attempts INT NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS sepay_last_check_at DATETIME(6),
 ADD COLUMN IF NOT EXISTS sepay_last_check_result VARCHAR(80);
CREATE INDEX IF NOT EXISTS idx_payments_sepay_due ON payments(provider,sepay_next_check_at,sepay_lease_until,id);
ALTER TABLE payment_events
 ADD COLUMN IF NOT EXISTS review_note VARCHAR(1000),
 ADD COLUMN IF NOT EXISTS reviewed_by BIGINT UNSIGNED,
 ADD COLUMN IF NOT EXISTS reviewed_at DATETIME(6);
CREATE INDEX IF NOT EXISTS idx_payment_events_review ON payment_events(provider,processing_status,reviewed_at,id);
-- END V011__sepay_automation_review.sql

-- BEGIN V012__sepay_refund_execution.sql
-- A claimed provider intent is never converted back to a manual refund.
-- Nullable columns preserve every existing refund and its proof workflow.
ALTER TABLE refunds
    ADD COLUMN IF NOT EXISTS sepay_execution_state VARCHAR(20),
    ADD COLUMN IF NOT EXISTS sepay_request_key VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin,
    ADD COLUMN IF NOT EXISTS sepay_transaction_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    ADD COLUMN IF NOT EXISTS sepay_bank_account_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    ADD COLUMN IF NOT EXISTS sepay_original_reference VARCHAR(150) CHARACTER SET ascii COLLATE ascii_bin,
    ADD COLUMN IF NOT EXISTS sepay_refund_id VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin,
    ADD COLUMN IF NOT EXISTS sepay_requested_by BIGINT,
    ADD COLUMN IF NOT EXISTS sepay_requested_at DATETIME(6),
    ADD COLUMN IF NOT EXISTS sepay_checked_at DATETIME(6),
    ADD COLUMN IF NOT EXISTS sepay_attempts INT NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS sepay_retry_at DATETIME(6),
    ADD COLUMN IF NOT EXISTS sepay_lease_until DATETIME(6),
    ADD COLUMN IF NOT EXISTS sepay_lease_token CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    ADD COLUMN IF NOT EXISTS sepay_error_code VARCHAR(80);
CREATE UNIQUE INDEX IF NOT EXISTS uq_refunds_sepay_request_key ON refunds(sepay_request_key);
CREATE UNIQUE INDEX IF NOT EXISTS uq_refunds_sepay_refund_id ON refunds(sepay_refund_id);
CREATE INDEX IF NOT EXISTS idx_refunds_sepay_due ON refunds(status,sepay_execution_state,sepay_retry_at,sepay_lease_until);
-- END V012__sepay_refund_execution.sql

-- BEGIN V013__tv5_vector_and_reindex_outbox.sql
-- TV5: Bảng lưu vector catalog cho Spring AI (MariaDB 11.7+/12.2) và hàng đợi reindex bền vững
-- Áp dụng theo thứ tự sau V001..V012. Không chạy lại V001 trên database đang có dữ liệu.

CREATE TABLE IF NOT EXISTS vector_store (
    id VARCHAR(36) NOT NULL PRIMARY KEY,
    content LONGTEXT NOT NULL,
    metadata JSON,
    embedding VECTOR(768) NOT NULL,
    VECTOR INDEX idx_vector_store_embedding (embedding) M=6 DISTANCE=cosine
) ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS commerce_vector_reindex_outbox (
    id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    product_id BIGINT NOT NULL,
    action VARCHAR(20) NOT NULL DEFAULT 'UPSERT',
    state VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    attempts INT NOT NULL DEFAULT 0,
    next_attempt_at DATETIME(6) NOT NULL,
    last_error VARCHAR(500),
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    processed_at DATETIME(6),
    CONSTRAINT ck_vector_outbox_action CHECK (action IN ('UPSERT', 'DELETE')),
    CONSTRAINT ck_vector_outbox_state CHECK (state IN ('PENDING', 'RETRY', 'SENT', 'DEAD')),
    CONSTRAINT ck_vector_outbox_attempts CHECK (attempts >= 0),
    CONSTRAINT fk_vector_outbox_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE,
    KEY idx_vector_outbox_due (state, next_attempt_at, id)
) ENGINE=InnoDB;
-- END V013__tv5_vector_and_reindex_outbox.sql

-- BEGIN V014__commerce_vector_runtime.sql
-- Catalog ownership is nullable: pre-existing generic vector rows remain untouched.
ALTER TABLE vector_store
    ADD COLUMN IF NOT EXISTS catalog_product_id BIGINT,
    ADD COLUMN IF NOT EXISTS catalog_fingerprint CHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
    ADD COLUMN IF NOT EXISTS embedding_model VARCHAR(80),
    ADD COLUMN IF NOT EXISTS indexed_at DATETIME(6);
CREATE UNIQUE INDEX IF NOT EXISTS uq_vector_catalog_product ON vector_store(catalog_product_id);
ALTER TABLE vector_store ADD CONSTRAINT fk_vector_store_catalog
    FOREIGN KEY IF NOT EXISTS (catalog_product_id) REFERENCES products(id) ON DELETE CASCADE;

-- Claims remain PENDING/RETRY; lease tokens fence workers without changing V013 states.
ALTER TABLE commerce_vector_reindex_outbox
    ADD COLUMN IF NOT EXISTS requested_fingerprint CHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
    ADD COLUMN IF NOT EXISTS lease_token CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    ADD COLUMN IF NOT EXISTS lease_until DATETIME(6),
    ADD COLUMN IF NOT EXISTS requested_by BIGINT,
    ADD COLUMN IF NOT EXISTS retry_reason VARCHAR(1000),
    ADD COLUMN IF NOT EXISTS retried_by BIGINT,
    ADD COLUMN IF NOT EXISTS retried_at DATETIME(6);
CREATE INDEX IF NOT EXISTS idx_vector_outbox_product ON commerce_vector_reindex_outbox(product_id,id);
CREATE INDEX IF NOT EXISTS idx_vector_outbox_lease ON commerce_vector_reindex_outbox(state,lease_until,next_attempt_at,id);
-- END V014__commerce_vector_runtime.sql

-- BEGIN V015__catalog_management.sql
-- Additive and repeatable; keep SKU IDs referenced by carts/orders/inventory.
ALTER TABLE products ADD COLUMN IF NOT EXISTS version BIGINT NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS idx_catalog_variant_product_status_price ON product_variants(product_id,status,price,id);
CREATE INDEX IF NOT EXISTS idx_catalog_image_product_sort ON product_images(product_id,sort_order,id);
CREATE INDEX IF NOT EXISTS idx_catalog_room_product ON product_rooms(room_id,product_id);
CREATE INDEX IF NOT EXISTS idx_catalog_collection_product ON collection_products(collection_id,product_id);
CREATE INDEX IF NOT EXISTS idx_catalog_material_variant ON variant_materials(material_id,variant_id);
-- END V015__catalog_management.sql

